`timescale 1ns/1ps
`default_nettype none
// sync_fifo: parameterizable single-clock FIFO with first-word fall-through.
// Implements microarchitecture.md (explicit count register, LAST-compare
// pointer wrap, flags gate requests, combinational read of the oldest slot,
// synchronous active-low reset of pointers and count only).
module sync_fifo #(
    parameter integer DEPTH = 8,
    parameter integer WIDTH = 8
) (
    input  wire                       clk,
    input  wire                       rst_n,
    input  wire                       wr_en,
    input  wire [WIDTH-1:0]           wr_data,
    output wire                       full,
    input  wire                       rd_en,
    output wire [WIDTH-1:0]           rd_data,
    output wire                       empty,
    output wire [$clog2(DEPTH+1)-1:0] count
);
    localparam integer AW      = $clog2(DEPTH);
    localparam integer CW      = $clog2(DEPTH+1);
    localparam integer LAST_I  = DEPTH - 1;
    localparam integer ONE_I   = 1;
    localparam [AW-1:0] LAST    = LAST_I[AW-1:0];
    localparam [AW-1:0] PTR_ONE = ONE_I[AW-1:0];
    localparam [CW-1:0] DEPTH_C = DEPTH[CW-1:0];
    localparam [CW-1:0] CNT_ONE = ONE_I[CW-1:0];

    // Storage: datapath, not reset, written only outside reset.
    reg  [WIDTH-1:0] mem [0:DEPTH-1];

    reg  [AW-1:0] wr_ptr_q;
    reg  [AW-1:0] wr_ptr_d;
    reg  [AW-1:0] rd_ptr_q;
    reg  [AW-1:0] rd_ptr_d;
    reg  [CW-1:0] count_q;
    reg  [CW-1:0] count_d;

    // Flags are compares on the count register.
    assign full  = (count_q == DEPTH_C);
    assign empty = (count_q == {CW{1'b0}});
    assign count = count_q;

    // Accepted requests: the flags are the overflow/underflow policy.
    wire wr_acc  = wr_en && !full;
    wire rd_acc  = rd_en && !empty;
    wire wr_fire = rst_n && wr_acc;

    // First-word fall-through read of the oldest slot.
    assign rd_data = mem[rd_ptr_q];

    // Next-state logic.
    always @(*) begin
        wr_ptr_d = wr_ptr_q;
        if (wr_acc) begin
            if (wr_ptr_q == LAST) begin
                wr_ptr_d = {AW{1'b0}};
            end else begin
                wr_ptr_d = wr_ptr_q + PTR_ONE;
            end
        end
    end

    always @(*) begin
        rd_ptr_d = rd_ptr_q;
        if (rd_acc) begin
            if (rd_ptr_q == LAST) begin
                rd_ptr_d = {AW{1'b0}};
            end else begin
                rd_ptr_d = rd_ptr_q + PTR_ONE;
            end
        end
    end

    always @(*) begin
        count_d = count_q;
        case ({wr_acc, rd_acc})
            2'b10:   count_d = count_q + CNT_ONE;
            2'b01:   count_d = count_q - CNT_ONE;
            default: count_d = count_q;
        endcase
    end

    // State registers: synchronous active-low reset.
    always @(posedge clk) begin
        if (!rst_n) begin
            wr_ptr_q <= {AW{1'b0}};
            rd_ptr_q <= {AW{1'b0}};
            count_q  <= {CW{1'b0}};
        end else begin
            wr_ptr_q <= wr_ptr_d;
            rd_ptr_q <= rd_ptr_d;
            count_q  <= count_d;
        end
    end

    // Storage write.
    always @(posedge clk) begin
        if (wr_fire) begin
            mem[wr_ptr_q] <= wr_data;
        end
    end

`ifdef FORMAL
    reg f_past_valid;
    initial f_past_valid = 1'b0;
    always @(posedge clk) f_past_valid <= 1'b1;

    always @(*) begin
        if (!f_past_valid) assume (!rst_n);
    end

    wire [CW:0] f_depth  = {1'b0, DEPTH_C};
    wire [CW:0] f_rd_ext = {{(CW+1-AW){1'b0}}, rd_ptr_q};
    wire [CW:0] f_wr_ext = {{(CW+1-AW){1'b0}}, wr_ptr_q};
    wire [CW:0] f_sum    = {1'b0, count_q} + f_rd_ext;
    wire [CW:0] f_wr_exp = (f_sum >= f_depth) ? (f_sum - f_depth) : f_sum;

    // Structural invariants.
    always @(*) begin
        if (f_past_valid) begin
            assert (count_q <= DEPTH_C);
            assert (rd_ptr_q <= LAST);
            assert (wr_ptr_q <= LAST);
            assert (full == (count_q == DEPTH_C));
            assert (empty == (count_q == {CW{1'b0}}));
            assert (!(full && empty));
            assert (f_wr_ext == f_wr_exp);
        end
    end

    // Data integrity for one solver-chosen slot.
    (* anyconst *) reg [AW-1:0] f_addr;
    always @(*) assume (f_addr <= LAST);

    reg [WIDTH-1:0] f_data;
    always @(posedge clk) begin
        if (wr_fire && (wr_ptr_q == f_addr)) f_data <= wr_data;
    end

    wire [WIDTH-1:0] f_mem_word = mem[f_addr];
    wire [CW:0] f_addr_ext = {{(CW+1-AW){1'b0}}, f_addr};
    wire [CW:0] f_off  = (f_addr_ext >= f_rd_ext) ? (f_addr_ext - f_rd_ext)
                                                  : (f_addr_ext + f_depth - f_rd_ext);
    wire        f_used = (f_off < {1'b0, count_q});

    always @(*) begin
        if (f_past_valid && f_used) begin
            assert (f_mem_word == f_data);
            if (rd_ptr_q == f_addr) assert (rd_data == f_data);
        end
    end

    // Step properties.
    always @(posedge clk) begin
        if (f_past_valid) begin
            if (!$past(rst_n)) begin
                assert (count_q == {CW{1'b0}});
                assert (wr_ptr_q == {AW{1'b0}});
                assert (rd_ptr_q == {AW{1'b0}});
                assert (empty);
                assert (!full);
            end else begin
                case ({$past(wr_acc), $past(rd_acc)})
                    2'b10:   assert (count_q == $past(count_q) + CNT_ONE);
                    2'b01:   assert (count_q == $past(count_q) - CNT_ONE);
                    default: assert (count_q == $past(count_q));
                endcase
                if (!$past(wr_acc)) assert (wr_ptr_q == $past(wr_ptr_q));
                if (!$past(rd_acc)) assert (rd_ptr_q == $past(rd_ptr_q));
                if ($past(wr_en && full)) begin
                    assert (wr_ptr_q == $past(wr_ptr_q));
                    assert (count_q <= $past(count_q));
                    assert (f_mem_word == $past(f_mem_word));
                end
                if ($past(rd_en && empty)) begin
                    assert (rd_ptr_q == $past(rd_ptr_q));
                    assert (count_q >= $past(count_q));
                end
            end
        end
    end

    // Covers: reach full, and return to empty after full.
    reg f_was_full;
    always @(posedge clk) begin
        if (!rst_n) f_was_full <= 1'b0;
        else if (full) f_was_full <= 1'b1;
    end

    always @(*) begin
        if (f_past_valid && rst_n) begin
            cover (full);
            cover (f_was_full && empty);
        end
    end
`endif

endmodule
`default_nettype wire
=== END FILE ===
