`timescale 1ns/1ps
`default_nettype none
// Self-checking testbench for sync_fifo: two DUTs (DEPTH 8 x WIDTH 8 and
// DEPTH 5 x WIDTH 12) on one stimulus, each against a reference queue.
module sync_fifo_tb;
    reg          clk;
    reg          rst_n;
    reg          wr_en;
    reg          rd_en;
    reg  [11:0]  stim_data;
    reg          final_check;
    reg  [31:0]  rnd;
    reg  [1:0]   wbias;
    reg  [1:0]   rbias;
    reg  [8*64-1:0] nonce;
    reg  [31:0]  total_passed;
    reg  [31:0]  total_failed;
    wire [31:0]  p8;
    wire [31:0]  f8;
    wire [31:0]  p5;
    wire [31:0]  f5;
    integer      i;
    integer      ph;

    initial clk = 1'b0;
    always #5 clk = ~clk;

    sync_fifo_tb_check #(.DEPTH(8), .WIDTH(8)) u_c8 (
        .clk(clk), .rst_n(rst_n), .wr_en(wr_en), .rd_en(rd_en),
        .wr_data(stim_data[7:0]), .final_check(final_check),
        .passed(p8), .failed(f8)
    );

    sync_fifo_tb_check #(.DEPTH(5), .WIDTH(12)) u_c5 (
        .clk(clk), .rst_n(rst_n), .wr_en(wr_en), .rd_en(rd_en),
        .wr_data(stim_data), .final_check(final_check),
        .passed(p5), .failed(f5)
    );

    task cyc;
        input r;
        input w;
        input rd;
        begin
            @(negedge clk);
            rst_n     = r;
            wr_en     = w;
            rd_en     = rd;
            rnd       = $random;
            stim_data = rnd[11:0];
        end
    endtask

    task rcyc;
        input r;
        begin
            @(negedge clk);
            rst_n     = r;
            rnd       = $random;
            wr_en     = (rnd[1:0] < wbias);
            rd_en     = (rnd[3:2] < rbias);
            stim_data = rnd[15:4];
        end
    endtask

    initial begin
        rst_n       = 1'b0;
        wr_en       = 1'b0;
        rd_en       = 1'b0;
        stim_data   = 12'd0;
        final_check = 1'b0;
        wbias       = 2'd2;
        rbias       = 2'd2;
        rnd         = 32'd0;
        nonce       = {(8*64){1'b0}};
        if ($value$plusargs("nirmaan_nonce=%s", nonce) == 0) nonce = {(8*64){1'b0}};

        // Reset.
        for (i = 0; i < 3; i = i + 1) cyc(1'b0, 1'b0, 1'b0);
        // Read while empty.
        cyc(1'b1, 1'b0, 1'b1);
        cyc(1'b1, 1'b0, 1'b1);
        // Fill to full and write while full.
        for (i = 0; i < 10; i = i + 1) cyc(1'b1, 1'b1, 1'b0);
        // Write and read together at full, then in between.
        cyc(1'b1, 1'b1, 1'b1);
        cyc(1'b1, 1'b1, 1'b1);
        // Drain to empty and read while empty.
        for (i = 0; i < 10; i = i + 1) cyc(1'b1, 1'b0, 1'b1);
        // Write and read together at empty, then in between.
        cyc(1'b1, 1'b1, 1'b1);
        cyc(1'b1, 1'b1, 1'b1);
        cyc(1'b1, 1'b1, 1'b1);
        // Partial fill, then reset during traffic with requests held.
        cyc(1'b1, 1'b1, 1'b0);
        cyc(1'b1, 1'b1, 1'b0);
        cyc(1'b1, 1'b1, 1'b0);
        cyc(1'b0, 1'b1, 1'b1);
        cyc(1'b0, 1'b1, 1'b0);
        cyc(1'b1, 1'b0, 1'b0);
        // Random traffic with varying bias and stalls on both sides.
        for (ph = 0; ph < 40; ph = ph + 1) begin
            case (ph % 4)
                0:       begin wbias = 2'd3; rbias = 2'd1; end
                1:       begin wbias = 2'd1; rbias = 2'd3; end
                2:       begin wbias = 2'd2; rbias = 2'd2; end
                default: begin wbias = 2'd3; rbias = 2'd3; end
            endcase
            for (i = 0; i < 60; i = i + 1) rcyc(1'b1);
            if ((ph == 12) || (ph == 28)) begin
                rcyc(1'b0);
                rcyc(1'b0);
            end
        end
        // Final coverage evaluation.
        cyc(1'b1, 1'b0, 1'b0);
        @(negedge clk);
        final_check = 1'b1;
        @(negedge clk);
        final_check = 1'b0;
        @(negedge clk);
        total_passed = p8 + p5;
        total_failed = f8 + f5;
        if (total_passed == 32'd0) begin
            $error("sync_fifo_tb: no check passed");
            total_failed = total_failed + 32'd1;
        end
        $display("NIRMAAN-SIM %0s %0d passed, %0d failed", nonce, total_passed, total_failed);
        $finish;
    end
endmodule

// One DUT with its reference queue and coverage counters.
module sync_fifo_tb_check #(
    parameter integer DEPTH = 8,
    parameter integer WIDTH = 8
) (
    input  wire             clk,
    input  wire             rst_n,
    input  wire             wr_en,
    input  wire             rd_en,
    input  wire [WIDTH-1:0] wr_data,
    input  wire             final_check,
    output reg  [31:0]      passed,
    output reg  [31:0]      failed
);
    localparam integer AW      = $clog2(DEPTH);
    localparam integer CW      = $clog2(DEPTH+1);
    localparam integer LAST_I  = DEPTH - 1;
    localparam integer ONE_I   = 1;
    localparam [AW-1:0] LAST    = LAST_I[AW-1:0];
    localparam [AW-1:0] PTR_ONE = ONE_I[AW-1:0];
    localparam [CW-1:0] DEPTH_C = DEPTH[CW-1:0];
    localparam [CW-1:0] CNT_ONE = ONE_I[CW-1:0];
    localparam [CW-1:0] CNT_ZERO = {CW{1'b0}};

    wire             full;
    wire             empty;
    wire [WIDTH-1:0] rd_data;
    wire [CW-1:0]    count;

    sync_fifo #(.DEPTH(DEPTH), .WIDTH(WIDTH)) u_dut (
        .clk(clk), .rst_n(rst_n),
        .wr_en(wr_en), .wr_data(wr_data), .full(full),
        .rd_en(rd_en), .rd_data(rd_data), .empty(empty),
        .count(count)
    );

    reg [WIDTH-1:0] q [0:DEPTH-1];
    reg [AW-1:0]    head;
    reg [AW-1:0]    tail;
    reg [CW-1:0]    mcount;
    reg             started;
    reg             saw_full;
    reg             wacc;
    reg             racc;
    reg             exp_full;
    reg             exp_empty;
    reg [31:0]      cov_full;
    reg [31:0]      cov_wr_full;
    reg [31:0]      cov_rd_empty;
    reg [31:0]      cov_both_empty;
    reg [31:0]      cov_both_full;
    reg [31:0]      cov_both_mid;
    reg [31:0]      cov_drain;
    reg [31:0]      cov_wrap;
    reg [31:0]      cov_rst_traffic;

    initial begin
        passed          = 32'd0;
        failed          = 32'd0;
        head            = {AW{1'b0}};
        tail            = {AW{1'b0}};
        mcount          = CNT_ZERO;
        started         = 1'b0;
        saw_full        = 1'b0;
        wacc            = 1'b0;
        racc            = 1'b0;
        exp_full        = 1'b0;
        exp_empty       = 1'b1;
        cov_full        = 32'd0;
        cov_wr_full     = 32'd0;
        cov_rd_empty    = 32'd0;
        cov_both_empty  = 32'd0;
        cov_both_full   = 32'd0;
        cov_both_mid    = 32'd0;
        cov_drain       = 32'd0;
        cov_wrap        = 32'd0;
        cov_rst_traffic = 32'd0;
    end

    task tally;
        input ok;
        begin
            if (ok) passed = passed + 32'd1;
            else    failed = failed + 32'd1;
        end
    endtask

    always @(posedge clk) begin
        exp_full  = (mcount == DEPTH_C);
        exp_empty = (mcount == CNT_ZERO);
        // Check the state left by the previous edge against the model.
        if (started) begin
            if (count !== mcount)
                $error("sync_fifo D%0d W%0d t=%0t: count %0d, expected %0d", DEPTH, WIDTH, $time, count, mcount);
            tally(count === mcount);
            if (full !== exp_full)
                $error("sync_fifo D%0d W%0d t=%0t: full %b, expected %b", DEPTH, WIDTH, $time, full, exp_full);
            tally(full === exp_full);
            if (empty !== exp_empty)
                $error("sync_fifo D%0d W%0d t=%0t: empty %b, expected %b", DEPTH, WIDTH, $time, empty, exp_empty);
            tally(empty === exp_empty);
            if (!exp_empty) begin
                if (rd_data !== q[head])
                    $error("sync_fifo D%0d W%0d t=%0t: rd_data %h, expected %h", DEPTH, WIDTH, $time, rd_data, q[head]);
                tally(rd_data === q[head]);
            end
        end
        // Update the model for this edge.
        if (!rst_n) begin
            if (started && (mcount != CNT_ZERO)) cov_rst_traffic = cov_rst_traffic + 32'd1;
            mcount   = CNT_ZERO;
            head     = {AW{1'b0}};
            tail     = {AW{1'b0}};
            saw_full = 1'b0;
            started  = 1'b1;
        end else if (started) begin
            wacc = wr_en && !exp_full;
            racc = rd_en && !exp_empty;
            if (exp_full) begin
                cov_full = cov_full + 32'd1;
                saw_full = 1'b1;
            end
            if (exp_empty && saw_full) cov_drain = cov_drain + 32'd1;
            if (wr_en && exp_full) cov_wr_full = cov_wr_full + 32'd1;
            if (rd_en && exp_empty) cov_rd_empty = cov_rd_empty + 32'd1;
            if (wr_en && rd_en && exp_empty) cov_both_empty = cov_both_empty + 32'd1;
            if (wr_en && rd_en && exp_full) cov_both_full = cov_both_full + 32'd1;
            if (wr_en && rd_en && !exp_empty && !exp_full) cov_both_mid = cov_both_mid + 32'd1;
            if (racc) begin
                if (head == LAST) head = {AW{1'b0}};
                else              head = head + PTR_ONE;
            end
            if (wacc) begin
                q[tail] = wr_data;
                if (tail == LAST) begin
                    cov_wrap = cov_wrap + 32'd1;
                    tail = {AW{1'b0}};
                end else begin
                    tail = tail + PTR_ONE;
                end
            end
            if (wacc && !racc)      mcount = mcount + CNT_ONE;
            else if (racc && !wacc) mcount = mcount - CNT_ONE;
        end
        // Coverage verdicts.
        if (final_check) begin
            if (cov_full == 32'd0)        $error("sync_fifo D%0d: never filled to full", DEPTH);
            tally(cov_full != 32'd0);
            if (cov_wr_full == 32'd0)     $error("sync_fifo D%0d: no write while full", DEPTH);
            tally(cov_wr_full != 32'd0);
            if (cov_drain == 32'd0)       $error("sync_fifo D%0d: never drained to empty after full", DEPTH);
            tally(cov_drain != 32'd0);
            if (cov_rd_empty == 32'd0)    $error("sync_fifo D%0d: no read while empty", DEPTH);
            tally(cov_rd_empty != 32'd0);
            if (cov_both_empty == 32'd0)  $error("sync_fifo D%0d: no write and read together when empty", DEPTH);
            tally(cov_both_empty != 32'd0);
            if (cov_both_full == 32'd0)   $error("sync_fifo D%0d: no write and read together when full", DEPTH);
            tally(cov_both_full != 32'd0);
            if (cov_both_mid == 32'd0)    $error("sync_fifo D%0d: no write and read together in between", DEPTH);
            tally(cov_both_mid != 32'd0);
            if (cov_wrap == 32'd0)        $error("sync_fifo D%0d: no pointer wrap-around", DEPTH);
            tally(cov_wrap != 32'd0);
            if (cov_rst_traffic == 32'd0) $error("sync_fifo D%0d: no reset during traffic", DEPTH);
            tally(cov_rst_traffic != 32'd0);
        end
    end
endmodule
`default_nettype wire
